scripts.小孩对话.txt:
//和孩子对话
	
	If ($Zhujiarenshen == 0) @Talk0;
	If ($Zhujiarenshen == 1) @Talk1;

@Talk0:
	Say("朱盈：大姐姐，和我一起堆一个好大好大的雪人，好不好？", 0);
	Say("张琳心：对不起，姐姐有很重要的事，以后再陪你玩吧！", 101);
	Return;
	
@Talk1:
	Say("朱盈：呜呜……你抢了我们的东西，等我大哥回来他一定会去抓你的。", 0);
	Say("张琳心：对不起，小妹妹，我只是为了救人……", 104);
	Return;

